CREATE TABLE public.organization_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),created_by uuid NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',used_by uuid,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.organization_invites TO authenticated; GRANT ALL ON public.organization_invites TO service_role;
ALTER TABLE public.organization_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invites_admin ON public.organization_invites FOR SELECT TO authenticated USING(public.roomly_admin(organization_id));
CREATE INDEX invites_org_idx ON public.organization_invites(organization_id);
CREATE FUNCTION public.roomly_invite(org uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code uuid; BEGIN IF NOT public.roomly_admin(org) THEN RAISE EXCEPTION 'Wymagane uprawnienia administratora.'; END IF; INSERT INTO public.organization_invites(organization_id,created_by) VALUES(org,auth.uid()) RETURNING token INTO code; INSERT INTO public.audit_events(organization_id,user_id,action) VALUES(org,auth.uid(),'invite_created'); RETURN code; END $$;
CREATE FUNCTION public.roomly_join(code uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invite public.organization_invites; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Zaloguj się.'; END IF; IF EXISTS(SELECT 1 FROM public.memberships WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Masz już organizację.'; END IF; SELECT * INTO invite FROM public.organization_invites WHERE token=code AND used_at IS NULL AND expires_at>now() FOR UPDATE; IF invite.id IS NULL THEN RAISE EXCEPTION 'Kod jest nieprawidłowy, wygasł lub został wykorzystany.'; END IF; INSERT INTO public.memberships(organization_id,user_id) VALUES(invite.organization_id,auth.uid()); INSERT INTO public.user_roles(organization_id,user_id,role) VALUES(invite.organization_id,auth.uid(),'employee'); UPDATE public.organization_invites SET used_at=now(),used_by=auth.uid() WHERE id=invite.id; INSERT INTO public.audit_events(organization_id,user_id,action) VALUES(invite.organization_id,auth.uid(),'member_joined'); RETURN invite.organization_id; END $$;
REVOKE ALL ON FUNCTION public.roomly_invite(uuid), public.roomly_join(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.roomly_invite(uuid), public.roomly_join(uuid) TO authenticated,service_role;